import {useEffect,useState} from 'react';
import {defineLocalTool,type LocalToolJson,type LocalToolProps,type LocalToolSnapshot} from '@/engines/local/sdk';
type State={version:1;notes:string};
const valid=(value:LocalToolJson):value is State=>!!value&&typeof value==='object'&&!Array.isArray(value)&&value.version===1&&typeof value.notes==='string';
function View({client}:LocalToolProps<State>){const [snapshot,setSnapshot]=useState<LocalToolSnapshot<State>|null>(null),[notes,setNotes]=useState(''),[status,setStatus]=useState('');useEffect(()=>{let active=true;void client.read().then(row=>{if(active){setSnapshot(row);setNotes(row.data.notes);}});return()=>{active=false;};},[client]);return <section><h2>Compiled source tool</h2><textarea aria-label="Native SDK notes" value={notes} onChange={event=>setNotes(event.target.value)}/><button disabled={!snapshot} onClick={()=>void client.save({version:1,notes},snapshot!.revision).then(row=>{setSnapshot(row);setStatus('Saved');}).catch(()=>setStatus('Conflict; draft retained'))}>Save compiled notes</button><button onClick={()=>void client.openDocument('codex','sdk-native-card')}>Open source card</button><p role="status">{status}</p></section>;}
const object={type:'object' as const,properties:{},additionalProperties:false};
function wave(){const bytes=new Uint8Array(32044),view=new DataView(bytes.buffer),text=(offset:number,value:string)=>[...value].forEach((char,index)=>bytes[offset+index]=char.charCodeAt(0));text(0,'RIFF');view.setUint32(4,32036,true);text(8,'WAVE');text(12,'fmt ');view.setUint32(16,16,true);view.setUint16(20,1,true);view.setUint16(22,1,true);view.setUint32(24,16000,true);view.setUint32(28,32000,true);view.setUint16(32,2,true);view.setUint16(34,16,true);text(36,'data');view.setUint32(40,32000,true);return bytes;}
export default defineLocalTool<State>({namespace:'tests.native',name:{en:'Native source tool',es:'Herramienta fuente nativa'},description:{en:'Synthetic compiled SDK coverage.',es:'Cobertura sintética del SDK compilado.'},initialState:{version:1,notes:''},validateState:valid,component:View,operations:[
 {id:'inventory',description:{en:'Total a typed inventory request.',es:'Sumar un inventario tipado.'},writes:false,inputSchema:{type:'object',properties:{items:{type:'array',minItems:1,uniqueItems:true,items:{type:'object',properties:{name:{type:'string',minLength:1,maxLength:8},quantity:{type:'integer',minimum:1}},required:['name','quantity'],additionalProperties:false}}},required:['items'],additionalProperties:false},run:async(input)=>({total:(input.items as {name:string;quantity:number}[]).reduce((sum,row)=>sum+row.quantity,0)})},
 {id:'inspect',description:{en:'Read effective state and world data.',es:'Leer estado y datos efectivos.'},writes:false,inputSchema:object,run:async(_input,client)=>{const card=await client.world.read('codex','sdk-native-card');return{state:await client.read(),cards:await client.queryCodex(),fields:card?.projection?.fields??{},search:(await client.search('SDK')).map(row=>row.title),media:(await client.media.list()).map(row=>row.title),variantsAvailable:!!client.world.variants,documentKinds:(await Promise.all(['dialog-scene','codex','writings','maps','worldgen','board','timeline','notes','dictionary','tables','genealogy','character-sheets','radar','model-viewer','media'].map(async kind=>[kind,(await client.world.list(kind as 'codex')).length])))} as unknown as LocalToolJson;}},
 {id:'append',description:{en:'Append authored text using the supplied revision.',es:'Añadir texto con revisión.'},writes:true,inputSchema:{type:'object',properties:{text:{type:'string',minLength:1},revision:{type:['integer','null'],minimum:0}},required:['text','revision'],additionalProperties:false},run:async(input,client)=>{const row=await client.read();return await client.save({version:1,notes:row.data.notes+String(input.text)},input.revision as number|null) as unknown as LocalToolJson;}},
 {id:'fail_after_save',description:{en:'Prove a failed operation rolls back state.',es:'Probar rollback.'},writes:true,inputSchema:object,run:async(_input,client)=>{const row=await client.read();await client.save({version:1,notes:'MUST ROLL BACK'},row.revision);throw new Error('synthetic_operation_failure');}},
 {id:'fail_after_world',description:{en:'Prove a normal domain edit rolls back with its source operation.',es:'Probar rollback de edición normal.'},writes:true,inputSchema:object,run:async(_input,client)=>{await client.callTool('wh_update_codex_entry',{id:'sdk-native-card',title:'MUST ROLL BACK'});throw new Error('synthetic_world_operation_failure');}},
 {id:'lying_query',description:{en:'Prove query clients cannot save.',es:'Probar query de lectura.'},writes:false,inputSchema:object,run:async(_input,client)=>{const row=await client.read();return await client.save({version:1,notes:'MUST NOT WRITE'},row.revision) as unknown as LocalToolJson;}},
 {id:'rename_card',description:{en:'Reuse normal document writes in Base or variants.',es:'Reutilizar escritura normal.'},writes:true,inputSchema:{type:'object',properties:{title:{type:'string',minLength:1}},required:['title'],additionalProperties:false},run:async(input,client)=>{if(client.world.variants){const read=(await client.world.read('codex','sdk-native-card'))!;await client.world.variants.save('codex',{...read.document,root:{...read.document.root,title:String(input.title)}},read.version);return{saved:true};}return client.callTool('wh_update_codex_entry',{id:'sdk-native-card',title:input.title});}},
 {id:'create_note',description:{en:'Use the normal scoped note operation.',es:'Usar notas normales.'},writes:true,inputSchema:{type:'object',properties:{text:{type:'string'}},required:['text'],additionalProperties:false},run:(input,client)=>client.callTool('wh_create_note',{text:input.text,kind:'idea'})},
 {id:'foreign_card',description:{en:'Prove the client passes normal project ownership.',es:'Probar contexto del proyecto.'},writes:true,inputSchema:object,run:(_input,client)=>client.callTool('wh_update_codex_entry',{id:'sdk-foreign-card',title:'MUST NOT CHANGE'})},
 {id:'import_audio',description:{en:'Import normal local media without encoding it as tool state.',es:'Importar audio normal.'},writes:true,inputSchema:object,run:async(_input,client)=>{const row=await client.media.import(new File([wave()],'SDK audio.wav',{type:'audio/wav'}));return{id:row.id};}},
]});
